"""Audit services against SPEC.md rev 7. Writes findings/svc-XX.json."""
import ast
import json
import re
from pathlib import Path

ROOT = Path('/private/var/folders/w_/swqg2n117dzdrptxy6074cqw0000gp/T/w/f4c9cb678e78')
SERVICES = ROOT / 'services'
FINDINGS = ROOT / 'findings'
LFS_FIRST = 'version https://git-lfs.github.com/spec/v1'

def is_lfs_pointer(path):
    try:
        with path.open('rb') as fh:
            return fh.readline().decode('utf-8', 'replace').rstrip('\r\n') == LFS_FIRST
    except OSError:
        return False

def any_lfs(service_dir):
    return any(is_lfs_pointer(p) for p in service_dir.rglob('*') if p.is_file())

def load_json(path):
    try:
        return json.loads(path.read_text())
    except Exception:
        return {}

def parse_py(path):
    try:
        return ast.parse(path.read_text(), filename=str(path))
    except Exception:
        return None

def py_files(service_dir):
    return sorted((service_dir / 'src').rglob('*.py')) if (service_dir / 'src').is_dir() else []

def string_constants(tree):
    for node in ast.walk(tree):
        if isinstance(node, ast.Constant) and isinstance(node.value, str):
            yield node.value
        elif isinstance(node, ast.Constant) and isinstance(node.value, bytes):
            try:
                yield node.value.decode('utf-8')
            except UnicodeDecodeError:
                pass

def print_calls(tree):
    for node in ast.walk(tree):
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and node.func.id == 'print':
            yield node

def handler_names(tree):
    names = set()
    if tree is None:
        return names
    for node in ast.walk(tree):
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            names.add(node.name)
    return names

def has_docstring(node):
    try:
        body = node.body
        return bool(body) and isinstance(body[0], ast.Expr) and isinstance(body[0].value, ast.Constant) and isinstance(body[0].value.value, str)
    except Exception:
        return False

def audit(service_dir):
    name = service_dir.name
    if any_lfs(service_dir):
        return {'service': name, 'status': 'unverifiable', 'violations': [], 'details': ['LFS pointer']}
    config = load_json(service_dir / 'config.json')
    dockerfile_path = service_dir / 'Dockerfile'
    dockerfile = dockerfile_path.read_text() if dockerfile_path.is_file() else ''
    readme_path = service_dir / 'README.md'
    readme = readme_path.read_text() if readme_path.is_file() else ''
    codeowners_path = service_dir / 'CODEOWNERS'
    codeowners = codeowners_path.read_text() if codeowners_path.is_file() else ''
    requirements_path = service_dir / 'requirements.txt'
    requirements = requirements_path.read_text() if requirements_path.is_file() else ''
    handlers_path = service_dir / 'src' / 'handlers.py'
    handlers_tree = parse_py(handlers_path) if handlers_path.is_file() else None
    src_trees = [(p, parse_py(p)) for p in py_files(service_dir)]

    violations = []
    details = {}

    public = config.get('exposure') == 'public'

    # C1
    timeout = config.get('timeout_s')
    c1 = (not public) or (isinstance(timeout, (int, float)) and not isinstance(timeout, bool) and timeout <= 30)
