    bad_strings = []
    for p, tree in src_trees:
        if tree is None:
            continue
        for s in string_constants(tree):
            if s.startswith('sk_live_') or s.startswith('AKIA'):
                bad_strings.append(f'{p.relative_to(service_dir)}: {s[:20]}')
    details['C9'] = {'bad': bad_strings}

