        expected_handler = 'handle_' + segment
        c10 = expected_handler in handler_names(handlers_tree)
        details['C10'] = {'healthcheck': healthcheck, 'expected': expected_handler}
    else:
        details['C10'] = {'healthcheck': healthcheck, 'expected': None}

    # C11
    c11 = ('port' in config and 'metrics_port' in config and config.get('metrics_port') != config.get('port'))
    details['C11'] = {'port': config.get('port'), 'metrics_port': config.get('metrics_port')}

    # C12
    bad_req = []
    for raw in requirements.splitlines():
        line = raw.strip()
        if not line or line.startswith('#'):
