        # remove inline comment introduced by whitespace + #
        line = re.sub(r'\s+#.*$', '', line).strip()
        if not line:
            continue
        m = re.match(r'^[A-Za-z0-9][A-Za-z0-9._-]*(?:\[[^\]]+\])?\s*==\s*([^=<>!~;,\s]+)(?:\s*;.*)?$', line)
        if not m or '*' in m.group(1):
            bad_req.append(raw.strip())
    c12 = not bad_req
    details['C12'] = {'bad': bad_req}

    # C13
    log_level = config.get('log_level')
    c13 = log_level != 'DEBUG'
    details['C13'] = {'log_level': log_level}

    # C14
    max_body = config.get('max_body_kb')
    c14 = (not public) or (isinstance(max_body, (int, float)) and not isinstance(max_body, bool) and max_body <= 1024)
    details['C14'] = {'public': public, 'max_body_kb': max_body}

