    c15 = bool(test_files)
    details['C15'] = {'files': test_files}

    results = {'C1': c1, 'C2': c2, 'C3': c3 if 'c3' in locals() else True,
               'C4': c4, 'C5': c5, 'C6': c6, 'C7': c7, 'C8': c8,
               'C9': not bad_strings, 'C10': c10, 'C11': c11, 'C12': c12,
               'C13': c13, 'C14': c14, 'C15': c15}
    # C3 assignment is bad_print, fix explicitly
    results['C3'] = not bad_print
    violations = [f'C{i}' for i in range(1, 16) if not results[f'C{i}']]
    return {'service': name, 'status': 'compliant' if not violations else 'violations',
            'violations': violations, 'details': details}

def main():
    FINDINGS.mkdir(exist_ok=True)
