    for service_dir in sorted(SERVICES.iterdir()):
        if not service_dir.is_dir() or not service_dir.name.startswith('svc-'):
            continue
        r = audit(service_dir)
        details = r.pop('details')
        out = {'service': r['service'], 'status': r['status'], 'violations': r['violations']}
        (FINDINGS / (r['service'] + '.json')).write_text(json.dumps(out, indent=2) + '\n')
